1	package theme
2	
3	import (
4		"image/color"
5		"testing"
6	)
7	
8	// DEVDESK-764: every text colour of the palette reaches WCAG 1.4.3 (4.5:1) on
9	// the surface it is really painted on, on each of the 13 shipped themes. The
10	// measure of 2026-11-23 (docs/measurements/2026-11-23-sec-detail-contrast.md)
11	// found ColorDim, ColorSubTitleFg, ColorWarn and ColorFooterError below it.
12	//
13	// Surfaces, and why each colour is measured on the ones it has:
14	//
15	//   - background: ColorBackground, under everything (Rule 115).
16	//   - selected row: ColorTableLineSelected. A plain "normal" selection keeps
17	//     every cell's own foreground and repaints this background under it
18	//     (Rule 118, Rule 122), so any colour a table cell can take is read on it.
19	//   - raised surface: ColorCmdLineBg, which the chart, the inactive tab and the
20	//     disabled button sit on. It is the same hex as the selected row on every
21	//     shipped theme, but it is its own key, so it is measured on its own.
22	//
23	// ColorSubTitleFg only heads a block of text on the background. The footer
24	// colours are text on the background (the footer line); under the cursor they
25	// are the activity dot and the severity icon, a glyph held to 3:1 (WCAG 1.4.11).
26	const (
27		textMinContrast  = 4.5 // WCAG 1.4.3, text
28		glyphMinContrast = 3.0 // WCAG 1.4.11, graphical object
29	)
30	
31	type textInk struct {
32		what string
33		fg   func() color.Color
34		// on lists the surfaces the colour is painted on and the ratio each needs.
35		on []surfaceNeed
36	}
37	
38	type surfaceNeed struct {
39		surface string
40		bg      func() color.Color
41		min     float64
42	}
43	
44	var (
45		onBackground = func(min float64) surfaceNeed {
46			return surfaceNeed{"ColorBackground", func() color.Color { return ColorBackground }, min}
47		}
48		onSelectedRow = func(min float64) surfaceNeed {
49			return surfaceNeed{"ColorTableLineSelected", func() color.Color { return ColorTableLineSelected }, min}
50		}
51		onRaised = func(min float64) surfaceNeed {
52			return surfaceNeed{"ColorCmdLineBg", func() color.Color { return ColorCmdLineBg }, min}
53		}
54	)
55	
56	func textInks() []textInk {
57		return []textInk{
58			{"ColorText", func() color.Color { return ColorText },
59				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast), onRaised(textMinContrast)}},
60			{"ColorDim", func() color.Color { return ColorDim },
61				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast), onRaised(textMinContrast)}},
62			{"ColorSubTitleFg", func() color.Color { return ColorSubTitleFg },
63				[]surfaceNeed{onBackground(textMinContrast)}},
64			{"ColorWarn", func() color.Color { return ColorWarn },
65				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast)}},
66			{"ColorFooterWarn", func() color.Color { return ColorFooterWarn },
67				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
68			{"ColorFooterError", func() color.Color { return ColorFooterError },
69				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
70		}
71	}
72	
73	// Each failure names the theme, the colour, the surface and the measured ratio.
74	func TestEveryTextColourReachesItsContrastOnEveryTheme(t *testing.T) {
75		eachShippedTheme(t, func(t *testing.T, name string) {
76			for _, ink := range textInks() {
77				for _, need := range ink.on {
78					fg, bg := ink.fg(), need.bg()
79					ratio, err := ContrastRatio(fg, bg)
80					if err != nil {
81						t.Errorf("theme %s: %s on %s: %v", name, ink.what, need.surface, err)
82						continue
83					}
84					if ratio < need.min {
85						t.Errorf("theme %s: %s %s on %s %s is %.2f:1, want >= %.1f:1",
86							name, ink.what, Hex(fg), need.surface, Hex(bg), ratio, need.min)
87					}
88				}
89			}
90		})
91	}
92	
93	// A greyed control still has to be read: raising ColorDim is not enough when the
94	// label sits on a background of the same hue. The disabled button used to paint
95	// ColorDim on ColorButtonInactiveBg, which is the same hex on nine themes (1:1).
96	func TestTheDisabledButtonLabelReachesTextContrastOnEveryTheme(t *testing.T) {
97		eachShippedTheme(t, func(t *testing.T, name string) {
98			for _, focused := range []bool{false, true} {
99				s := ButtonStyle(focused, "disabled")
100				fg, bg := s.GetForeground(), s.GetBackground()
101				ratio, err := ContrastRatio(fg, bg)
102				if err != nil {
103					t.Errorf("theme %s: disabled button (focused=%v): %v", name, focused, err)
104					continue
105				}
106				if ratio < textMinContrast {
107					t.Errorf("theme %s: disabled button (focused=%v) label %s on %s is %.2f:1, want >= %.1f:1",
108						name, focused, Hex(fg), Hex(bg), ratio, textMinContrast)
109				}
110			}
111		})
112	}
113	
114	// Grey says "not now", and colour alone must not be the only thing that says it
115	// (WCAG 1.4.1): a disabled button is italic, an enabled one is not, and the
116	// focus mark of a disabled button is an inversion rather than a colour only.
117	func TestTheDisabledButtonDiffersFromAnEnabledOneByMoreThanColour(t *testing.T) {
118		withTheme(t, DefaultTheme())
119		for _, focused := range []bool{false, true} {
120			dis, en := ButtonStyle(focused, "disabled"), ButtonStyle(focused, "primary")
121			if !dis.GetItalic() {
122				t.Errorf("focused=%v: the disabled button is not italic", focused)
123			}
124			if en.GetItalic() {
125				t.Errorf("focused=%v: the enabled button is italic: the signal would carry nothing", focused)
126			}
127		}
128		if on, off := ButtonStyle(true, "disabled"), ButtonStyle(false, "disabled"); sameColor(on.GetBackground(), off.GetBackground()) {
129			t.Error("a focused disabled button keeps the unfocused background: the focus would be invisible")
130		}
131	}
132	
133	// Rule 118: an inactive tab is ColorDim on the tab's own background. The theme
134	// files used to set tab_inactive_fg on its own, to a tone that was never held to
135	// 4.5:1 (1.4:1 on catppuccin-latte).
136	func TestTheInactiveTabLabelReachesTextContrastOnEveryTheme(t *testing.T) {
137		eachShippedTheme(t, func(t *testing.T, name string) {
138			ratio, err := ContrastRatio(ColorTabInactiveFg, ColorTabInactiveBg)
139			if err != nil {
140				t.Fatal(err)
141			}
142			if ratio < textMinContrast {
143				t.Errorf("theme %s: ColorTabInactiveFg %s on ColorTabInactiveBg %s is %.2f:1, want >= %.1f:1",
144					name, Hex(ColorTabInactiveFg), Hex(ColorTabInactiveBg), ratio, textMinContrast)
145			}
146		})
147	}
148	
149	// ColorFooterError and ColorFooterWarn alias the CRITICAL and MEDIUM badge
150	// backgrounds, so the badge foregrounds have to read on them too.
151	func TestTheCriticalAndMediumBadgesReachTextContrastOnEveryTheme(t *testing.T) {
152		eachShippedTheme(t, func(t *testing.T, name string) {
153			pairs := []struct {
154				what   string
155				fg, bg color.Color
156			}{
157				{"CRITICAL badge (ColorSeverityCriticalFg on ColorFooterError)", ColorSeverityCriticalFg, ColorFooterError},
158				{"MEDIUM badge (ColorSeverityMediumFg on ColorFooterWarn)", ColorSeverityMediumFg, ColorFooterWarn},
159			}
160			for _, p := range pairs {
161				ratio, err := ContrastRatio(p.fg, p.bg)
162				if err != nil {
163					t.Errorf("theme %s: %s: %v", name, p.what, err)
164					continue
165				}
166				if ratio < textMinContrast {
167					t.Errorf("theme %s: %s, %s on %s is %.2f:1, want >= %.1f:1",
168						name, p.what, Hex(p.fg), Hex(p.bg), ratio, textMinContrast)
169				}
170			}
171		})
172	}
173	
174	// A theme written before severity_low existed, or by hand, may leave both LOW
175	// keys out. The fallback pair has to stay readable: ColorDim is a light text
176	// tone since DEVDESK-764 and would give ColorText on ColorDim, about 2:1.
177	func TestAThemeWithoutSeverityLowKeepsAReadableLowBadge(t *testing.T) {
178		for name, th := range shippedThemes(t) {
179			t.Run(name, func(t *testing.T) {
180				bare := *th
181				bare.SeverityLow, bare.SeverityLowFg = "", ""
182				withTheme(t, &bare)
183				ratio, err := ContrastRatio(ColorSeverityLowFg, ColorSeverityLow)
184				if err != nil {
185					t.Fatal(err)
186				}
187				if ratio < textMinContrast {
188					t.Errorf("theme %s without severity_low: %s on %s is %.2f:1, want >= %.1f:1",
189						name, Hex(ColorSeverityLowFg), Hex(ColorSeverityLow), ratio, textMinContrast)
190				}
191			})
192		}
193	}
