}

// hexToLab converts a colour to CIE Lab with a D65 white point.
func hexToLab(c color.Color) ([3]float64, error) {
	rgb, err := rgb8(c, "color distance")
	if err != nil {
		return [3]float64{}, err
	}
	var lin [3]float64
	for i, v := range rgb {
		f := float64(v) / 255
