// Button styles

// ButtonStyle returns a button style based on its state (focused or not)
func ButtonStyle(focused bool, variant string) lipgloss.Style {
	style := lipgloss.NewStyle().
		Padding(0, 2)

	// A disabled button is advertised but cannot act (Rule 130): dim italic text
	// on the raised surface (ColorCmdLineBg). It does not use the inactive button
	// background, which is the same hex as ColorDim on most themes and left the
	// label unreadable (DEVDESK-764). Italic is the signal that is not a colour:
	// no enabled button is italic. Under focus the two colours swap, so the
	// cursor is visible at the same width and the pair keeps its 4.5:1.
	if variant == "disabled" {
		style = style.Italic(true)
		if focused {
			return style.Background(ColorDim).Foreground(ColorCmdLineBg)
		}
		return style.Background(ColorCmdLineBg).Foreground(ColorDim)
	}

	if focused {
		switch variant {
		case "primary":
			return style.Bold(true).Background(ColorButtonBg).Foreground(ColorButtonFg)
		case "danger":
			return style.Bold(true).Background(ColorError).Foreground(ColorButtonFg)
		case "success":
			return style.Bold(true).Background(ColorOK).Foreground(ColorBlack)
		default:
			return style.Bold(true).Background(ColorButtonBg).Foreground(ColorButtonFg)
		}
	}

	switch variant {
	case "primary":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorButtonInactiveFg)
	case "danger":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorError)
	case "success":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorOK)
	case "secondary":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorButtonInactiveFg)
	default:
		return style.Background(ColorButtonInactiveBg).Foreground(ColorPrimary)
	}
}

