		{"low pair", rgb(130, 140, 160), rgb(100, 110, 130), 4.5},
		{"same colour", rgb(120, 120, 120), rgb(120, 120, 120), 4.5},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			nf, nb, de, err := minimalPair(c.fg, c.bg, c.min)
			if err != nil {
				t.Fatal(err)
			}
			if r, _ := ContrastRatio(nf, nb); r < c.min {
